// ------------------------------------------------------------------ numbers

fn skip_digits(b: &[u8], mut i: usize) -> usize {
    while i < b.len() && b[i].is_ascii_digit() {
        i += 1;
    }
    i
}

/// Reports whether `s` is a JSON number.
fn is_number(s: &str) -> bool {
    let b = s.as_bytes();
    let mut i = 0;
    if i < b.len() && b[i] == b'-' {
        i += 1;
    }
    if i >= b.len() {
        return false;
    }
    if b[i] == b'0' {
        i += 1;
    } else if b[i].is_ascii_digit() {
        i = skip_digits(b, i);
    } else {
        return false;
    }
    if i < b.len() && b[i] == b'.' {
        let start = i + 1;
        i = skip_digits(b, start);
        if i == start {
            return false;
        }
    }
    if i < b.len() && (b[i] == b'e' || b[i] == b'E') {
        i += 1;
        if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
            i += 1;
        }
        let start = i;
        i = skip_digits(b, start);
        if i == start {
            return false;
        }
    }
    i == b.len()
}

/// The values a member of type `ctype` (a bitfield `bits` wide, if `bits`)
/// holds, as the magnitude of the lowest and the highest; a char takes -128
/// to 255, as in the C and C++ runtimes.
fn range(ctype: &str, bits: u32) -> (u64, u64) {
    let (signed, mut width) = match ctype {
        "char" => return (128, 255),
        "unsigned char" | "uint8_t" => (false, 8),
        "int8_t" => (true, 8),
        "uint16_t" => (false, 16),
        "int16_t" => (true, 16),
        "uint32_t" => (false, 32),
        "int32_t" => (true, 32),
        "uint64_t" => (false, 64),
        _ => (true, 64),
    };
    if bits > 0 {
        width = bits;
    }
    if signed {
        (1 << (width - 1), (1 << (width - 1)) - 1)
    } else if width == 64 {
        (0, u64::MAX)
    } else {
        (0, (1 << width) - 1)
    }
}

/// The exact integer a JSON number stands for ("12", "1.2e1", "120e-1") as
/// its sign and magnitude; `None` if it is not a whole number or needs more
/// than 64 bits.
fn integer_value(text: &str) -> Option<(bool, u64)> {
    if !is_number(text) {
        return None;
    }
    let negative = text.starts_with('-');
    let body = text.trim_start_matches('-').replace('E', "e");
    let (mantissa, exponent_text) = match body.split_once('e') {
        Some((m, e)) => (m, Some(e)),
        None => (body.as_str(), None),
    };
    let (whole, fraction) = mantissa.split_once('.').unwrap_or((mantissa, ""));
    let mut exponent = -(fraction.len() as i64);
    if let Some(e) = exponent_text {
        let sign = if e.starts_with('-') { -1 } else { 1 };
        let digits = e
            .trim_start_matches(&['+', '-'][..])
            .trim_start_matches('0');
        // Beyond 100000 either way is beyond any 64-bit value.
        let mut value = 100_000;
        if digits.len() <= 6 {
            value = digits.parse::<i64>().unwrap_or(0).min(100_000);
        }
        exponent += sign * value;
    }
    let all = format!("{whole}{fraction}");
    let digits = all.trim_start_matches('0');
    if digits.is_empty() {
        return Some((false, 0));
    }
    let significant = digits.trim_end_matches('0');
    let places = (digits.len() - significant.len()) as i64 + exponent;
    if places < 0 || significant.len() as i64 + places > 20 {
        return None;
    }
    let mut magnitude: u64 = 0;
    for c in format!("{significant}{}", "0".repeat(places as usize)).bytes() {
        magnitude = magnitude
            .checked_mul(10)?
            .checked_add(u64::from(c - b'0'))?;
    }
    Some((negative, magnitude))
}

/// The value, as the bits of a two's complement u64 that the member's type
/// converts to, if it is in range for `ctype` (a bitfield `bits` wide, if
/// `bits`). A char above 127 converts to the signed char C and C++ hold.
fn fit_integer(negative: bool, magnitude: u64, ctype: &str, bits: u32) -> Result<u64> {
    let (lo, hi) = range(ctype, bits);
    if (negative && magnitude > lo) || (!negative && magnitude > hi) {
        return Err(invalid(&format!("out of range for {ctype}")));
    }
    Ok(if negative {
        magnitude.wrapping_neg()
    } else {
        magnitude
    })
}

fn to_integer(text: &str, ctype: &str, bits: u32) -> Result<u64> {
    let (negative, magnitude) =
        integer_value(text).ok_or_else(|| invalid("not a whole number of at most 64 bits"))?;
    fit_integer(negative, magnitude, ctype, bits)
}

/// A decimal number, which `str::parse` takes, rounded straight to the type:
/// a float directly, not through a double, which could round twice. Too
/// large gives an infinity.
fn parse_real(text: &str, is_float: bool) -> f64 {
    if is_float {
        text.parse::<f32>().map_or(f64::NAN, f64::from)
    } else {
        text.parse::<f64>().unwrap_or(f64::NAN)
    }
}

/// A float or double member's value: "NaN", "Infinity" and "-Infinity" by
/// name, otherwise a JSON number rounded to the type; too large is invalid.
fn to_real(text: &str, ctype: &str) -> Result<f64> {
    match text {
        "NaN" => return Ok(f64::NAN),
        "Infinity" => return Ok(f64::INFINITY),
        "-Infinity" => return Ok(f64::NEG_INFINITY),
        _ => {}
    }
    if !is_number(text) {
        return Err(invalid("not a number"));
    }
    let value = parse_real(text, ctype == "float");
    if value.is_infinite() {
        return Err(invalid(&format!("too large for {ctype}")));
    }
    Ok(value)
}

/// The exact decimal digits (each 0 to 9) of a finite, nonzero value,
/// without trailing zeros, and the power of ten of the first. A double has
/// at most 767 significant digits, which std prints exactly.
fn exact_digits(value: f64) -> (Vec<u8>, i32) {
    let text = format!("{:.800e}", value.abs());
    let (mantissa, exponent) = text.split_once('e').unwrap_or((text.as_str(), "0"));
    let mut digits: Vec<u8> = mantissa
        .bytes()
        .filter(u8::is_ascii_digit)
        .map(|c| c - b'0')
        .collect();
    while digits.len() > 1 && digits.last() == Some(&0) {
        digits.pop();
    }
    (digits, exponent.parse().unwrap_or(0))
}

/// The exact digits rounded to `precision` digits, ties to even, as
/// printf's %.*e does, and the power of ten of the first.
fn rounded(exact: &[u8], exponent: i32, precision: usize) -> (Vec<u8>, i32) {
    let mut digits = exact[..exact.len().min(precision)].to_vec();
    if exact.len() <= precision {
        digits.resize(precision, 0);
        return (digits, exponent);
    }
    let next = exact[precision];
    // exact has no trailing zeros, so a digit after next is not zero.
    let up =
        next > 5 || (next == 5 && (exact.len() > precision + 1 || digits[precision - 1] % 2 == 1));
    if up {
        for i in (0..precision).rev() {
            if digits[i] != 9 {
                digits[i] += 1;
                return (digits, exponent);
            }
            digits[i] = 0;
        }
        // All nines: 99 becomes 100, one place up.
        digits.insert(0, 1);
        digits.truncate(precision);
        return (digits, exponent + 1);
    }
    (digits, exponent)
}

/// Reports whether digits * 10^(exponent - digits.len() + 1) reads back as
/// `value`.
fn reads_back(digits: &[u8], exponent: i32, value: f64, is_float: bool) -> bool {
    let mut text = String::with_capacity(digits.len() + 8);
    if value < 0.0 {
        text.push('-');
    }
    text.extend(digits.iter().map(|&d| char::from(b'0' + d)));
    text.push('e');
    text.push_str(&(exponent - (digits.len() as i32 - 1)).to_string());
    parse_real(&text, is_float) == value
}

/// Adds one to (`up`) or takes one from the last digit, carrying: the
/// digits, the exponent and false if the result is zero.
fn step(digits: &[u8], exponent: i32, up: bool) -> (Vec<u8>, i32, bool) {
    let mut d = digits.to_vec();
    let mut exponent = exponent;
    for i in (0..d.len()).rev() {
        if up {
            if d[i] != 9 {
                d[i] += 1;
                return (d, exponent, true);
            }
            d[i] = 0;
        } else {
            if d[i] != 0 {
                d[i] -= 1;
                break;
            }
            d[i] = 9;
        }
    }
    if up {
        // All nines: 99 becomes 100, one place up.
        d.insert(0, 1);
        d.pop();
        return (d, exponent + 1, true);
    }
    if d[0] == 0 {
        // 10 becomes 99, one place down.
        d.remove(0);
        d.push(9);
        exponent -= 1;
    }
    let nonzero = d.iter().any(|&x| x != 0);
    (d, exponent, nonzero)
}

/// A finite, nonzero value as the fewest significant digits that read back
/// as it, and the power of ten of the first one.
fn shortest(value: f64, is_float: bool) -> (Vec<u8>, i32) {
    let most = if is_float { 9 } else { 17 };
    let (exact, exact_exponent) = exact_digits(value);
    let mut digits = Vec::new();
    let mut exponent = 0;
    for precision in 1..=most {
        let (d, e) = rounded(&exact, exact_exponent, precision);
        if reads_back(&d, e, value, is_float) {
            digits = d;
            exponent = e;
            break;
        }
        // Next to a power of two the nearest decimal can miss while a
        // neighbour of it reads back.
        let mut found = None;
        for &up in &[true, false] {
            let (nd, ne, nonzero) = step(&d, e, up);
            if nonzero && nd.len() == d.len() && reads_back(&nd, ne, value, is_float) {
                found = Some((nd, ne));
                break;
            }
        }
        if let Some((nd, ne)) = found {
            digits = nd;
            exponent = ne;
            break;
        }
        digits = d;
        exponent = e;
    }
    while digits.len() > 1 && digits.last() == Some(&0) {
        digits.pop();
    }
    (digits, exponent)
}

/// A float or double as text: the shortest form that reads back exactly,
/// laid out as JavaScript's Number#toString does, but keeping -0; NaN,
/// Infinity and -Infinity by name.
fn real_text(value: f64, is_float: bool) -> String {
    if value.is_nan() {
        return "NaN".to_string();
    }
    if value.is_infinite() {
        return if value > 0.0 { "Infinity" } else { "-Infinity" }.to_string();
    }
    if value == 0.0 {
        return if value.is_sign_negative() { "-0" } else { "0" }.to_string();
    }
    let (digits, e) = shortest(value, is_float);
    let text: String = digits.iter().map(|&d| char::from(b'0' + d)).collect();
    let k = digits.len() as i32;
    let n = e + 1;
    let sign = if value < 0.0 { "-" } else { "" };
    if (k..=21).contains(&n) {
        return format!("{sign}{text}{}", "0".repeat((n - k) as usize));
    }
    if (1..=21).contains(&n) {
        let (whole, fraction) = text.split_at(n as usize);
        return format!("{sign}{whole}.{fraction}");
    }
    if (-5..=0).contains(&n) {
        return format!("{sign}0.{}{text}", "0".repeat((-n) as usize));
    }
    let (first, rest) = text.split_at(1);
    let point = if rest.is_empty() { "" } else { "." };
    if e < 0 {
        format!("{sign}{first}{point}{rest}e-{}", -e)
    } else {
        format!("{sign}{first}{point}{rest}e+{e}")
    }
}

/// A string member's bytes without its trailing NULs.
fn used(data: &[u8]) -> &[u8] {
    let n = data.iter().rposition(|&b| b != 0).map_or(0, |i| i + 1);
    &data[..n]
}

/// Fills `dst` with `text`, each character one byte (U+0000 to U+00FF),
/// zero-padded; invalid if there are more than `dst.len()`.
fn text_to_bytes(text: &[char], dst: &mut [u8]) -> Result<()> {
    if text.len() > dst.len() {
        return Err(invalid("string too long"));
    }
    if text.iter().any(|&c| u32::from(c) > 0xFF) {
        return Err(invalid("a character that is not one byte"));
    }
    dst.fill(0);
    for (d, &c) in dst.iter_mut().zip(text) {
        *d = u32::from(c) as u8;
    }
    Ok(())
}

/// `input` as characters; invalid if it is not UTF-8.
fn decode(input: &[u8]) -> Result<Vec<char>> {
    match std::str::from_utf8(input) {
        Ok(text) => Ok(text.chars().collect()),
        Err(_) => Err(invalid("not UTF-8")),
    }
}

fn is_space(c: char) -> bool {
    c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

fn has_prefix(s: &[char], i: usize, word: &str) -> bool {
    (i..).zip(word.chars()).all(|(at, c)| s.get(at) == Some(&c))
}

fn trim(text: &[char]) -> String {
    let s: String = text.iter().collect();
    s.trim_matches(is_space).to_string()
}

const HEX_DIGITS: &[u8; 16] = b"0123456789abcdef";

fn push_hex(out: &mut String, b: u8) {
    out.push(char::from(HEX_DIGITS[usize::from(b >> 4)]));
    out.push(char::from(HEX_DIGITS[usize::from(b & 15)]));
}

// ------------------------------------------------------------------ JSON

/// A parsed JSON value.
pub(crate) enum Json {
    Object(Vec<JsonMember>),
    Array(Vec<Json>),
    Str(Vec<char>),
    /// A number, as its text.
    Number(String),
    Bool,
    Null,
}

/// One member of a JSON object.
pub(crate) struct JsonMember {
    pub(crate) name: String,
    pub(crate) value: Json,
}

struct JsonParser {
    s: Vec<char>,
    i: usize,
}

impl JsonParser {
    fn peek(&self) -> Option<char> {
        self.s.get(self.i).copied()
    }

    fn space(&mut self) {
        while matches!(self.peek(), Some(c) if is_space(c)) {
            self.i += 1;
        }
    }

    fn expect(&mut self, c: char) -> Result<()> {
        if self.peek() != Some(c) {
            return Err(invalid(&format!("expected {c}")));
        }
        self.i += 1;
        Ok(())
    }

    fn literal(&mut self, word: &str) -> Result<()> {
        if !has_prefix(&self.s, self.i, word) {
            return Err(invalid(&format!("expected {word}")));
        }
        self.i += word.len();
        Ok(())
    }

    fn hex4(&mut self) -> Result<u32> {
        if self.i + 4 > self.s.len() {
            return Err(invalid("bad \\u escape"));
        }
        let mut cp = 0;
        for &c in &self.s[self.i..self.i + 4] {
            let v = c.to_digit(16).ok_or_else(|| invalid("bad \\u escape"))?;
            cp = cp * 16 + v;
        }
        self.i += 4;
        Ok(cp)
    }

    fn string(&mut self) -> Result<Vec<char>> {
        self.expect('"')?;
        let mut out = Vec::new();
        while let Some(c) = self.peek() {
            self.i += 1;
            if c == '"' {
                return Ok(out);
            }
            if c < '\u{20}' {
                return Err(invalid("control character in a string"));
            }
            if c != '\\' {
                out.push(c);
                continue;
            }
            let e = match self.peek() {
                Some(e) => e,
                None => break,
            };
            self.i += 1;
            match e {
                '"' | '\\' | '/' => out.push(e),
                'b' => out.push('\u{8}'),
                'f' => out.push('\u{c}'),
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                't' => out.push('\t'),
                'u' => {
                    let mut cp = self.hex4()?;
                    if (0xDC00..=0xDFFF).contains(&cp) {
                        return Err(invalid("lone low surrogate"));
                    }
                    if (0xD800..=0xDBFF).contains(&cp) {
                        self.literal("\\u")?;
                        let low = self.hex4()?;
                        if !(0xDC00..=0xDFFF).contains(&low) {
                            return Err(invalid("lone high surrogate"));
                        }
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
                    }
                    out.push(char::from_u32(cp).ok_or_else(|| invalid("bad \\u escape"))?);
                }
                _ => return Err(invalid("bad escape")),
            }
        }
        Err(invalid("unterminated string"))
    }

    fn number(&mut self) -> Result<String> {
        let start = self.i;
        while matches!(self.peek(), Some(c) if "0123456789+-.eE".contains(c)) {
            self.i += 1;
        }
        let text: String = self.s[start..self.i].iter().collect();
        if !is_number(&text) {
            return Err(invalid("bad number"));
        }
        Ok(text)
    }

    fn value(&mut self, depth: usize) -> Result<Json> {
        let c = self.peek().ok_or_else(|| invalid("expected a value"))?;
        match c {
            '{' | '[' => {
                let depth = depth + 1;
                if depth > MAX_DEPTH {
                    return Err(invalid("nested too deeply"));
                }
                let object = c == '{';
                let end = if object { '}' } else { ']' };
                let mut members = Vec::new();
                let mut items = Vec::new();
                self.i += 1;
                self.space();
                if self.peek() != Some(end) {
                    loop {
                        self.space();
                        if object {
                            let name: String = self.string()?.into_iter().collect();
                            self.space();
                            self.expect(':')?;
                            self.space();
                            let value = self.value(depth)?;
                            members.push(JsonMember { name, value });
                        } else {
                            items.push(self.value(depth)?);
                        }
                        self.space();
                        if self.peek() != Some(',') {
                            break;
                        }
                        self.i += 1;
                    }
                }
                self.expect(end)?;
                Ok(if object {
                    Json::Object(members)
                } else {
                    Json::Array(items)
                })
            }
            '"' => Ok(Json::Str(self.string()?)),
            't' => self.literal("true").map(|_| Json::Bool),
            'f' => self.literal("false").map(|_| Json::Bool),
            'n' => self.literal("null").map(|_| Json::Null),
            _ => Ok(Json::Number(self.number()?)),
        }
    }
}

/// Parses a whole JSON document, surrounding whitespace allowed. Invalid if
/// it is not well-formed JSON or nests too deeply.
pub(crate) fn parse_json(input: &[u8]) -> Result<Json> {
    let mut p = JsonParser {
        s: decode(input)?,
        i: 0,
    };
    p.space();
    let v = p.value(0)?;
    p.space();
    if p.i != p.s.len() {
        return Err(invalid("text after the value"));
    }
    Ok(v)
}

impl Json {
    /// The members of an object, in order, repeats and all.
    pub(crate) fn members(&self) -> Result<&[JsonMember]> {
        match self {
            Json::Object(members) => Ok(members),
            _ => Err(invalid("not an object")),
        }
    }

    /// A number member's text: a JSON number, or a string holding one (as
    /// 64-bit integers, NaN and the infinities are written).
    fn text(&self) -> Result<String> {
        match self {
            Json::Number(text) => Ok(text.clone()),
            Json::Str(chars) => Ok(chars.iter().collect()),
            _ => Err(invalid("not a number")),
        }
    }

    /// An integer member, which must be whole and in range, of `ctype` or of
    /// a bitfield `bits` wide.
    pub(crate) fn int(&self, ctype: &str, bits: u32) -> Result<u64> {
        to_integer(&self.text()?, ctype, bits)
    }

    /// A float or double member.
    pub(crate) fn real(&self, ctype: &str) -> Result<f64> {
        to_real(&self.text()?, ctype)
    }

    /// A string member, into `dst`: each character one byte.
    pub(crate) fn bytes(&self, dst: &mut [u8]) -> Result<()> {
        match self {
            Json::Str(chars) => text_to_bytes(chars, dst),
            _ => Err(invalid("not a string")),
        }
    }
}

/// Writes the canonical JSON form: no whitespace, members in order.
#[derive(Default)]
pub(crate) struct JsonWriter {
    out: String,
    first: bool,
}

impl JsonWriter {
    pub(crate) fn finish(self) -> String {
        self.out
    }

    pub(crate) fn begin_object(&mut self) {
        self.out.push('{');
        self.first = true;
    }

    pub(crate) fn end_object(&mut self) {
        self.out.push('}');
        self.first = false;
    }

    pub(crate) fn key(&mut self, name: &str) {
        if !self.first {
            self.out.push(',');
        }
        self.first = false;
        self.out.push('"');
        self.out.push_str(name);
        self.out.push_str("\":");
    }

    /// Types up to 32 bits but uint32_t (a char as signed).
    pub(crate) fn i32(&mut self, name: &str, v: i32) {
        self.key(name);
        self.out.push_str(&v.to_string());
    }

    pub(crate) fn u32(&mut self, name: &str, v: u32) {
        self.key(name);
        self.out.push_str(&v.to_string());
    }

    /// 64-bit integers are written as strings.
    pub(crate) fn i64(&mut self, name: &str, v: i64) {
        self.key(name);
        self.out.push_str(&format!("\"{v}\""));
    }

    pub(crate) fn u64(&mut self, name: &str, v: u64) {
        self.key(name);
        self.out.push_str(&format!("\"{v}\""));
    }

    pub(crate) fn f32(&mut self, name: &str, v: f32) {
        self.real(name, &real_text(f64::from(v), true));
    }

    pub(crate) fn f64(&mut self, name: &str, v: f64) {
        self.real(name, &real_text(v, false));
    }

    /// NaN and the infinities are written as strings.
    fn real(&mut self, name: &str, text: &str) {
        self.key(name);
        if is_number(text) {
            self.out.push_str(text);
        } else {
            self.out.push('"');
            self.out.push_str(text);
            self.out.push('"');
        }
    }

    /// A string member: its bytes up to the trailing NULs, printable ASCII
    /// as is (but " and \ escaped), every other byte as \u00xx.
    pub(crate) fn bytes(&mut self, name: &str, data: &[u8]) {
        self.key(name);
        self.out.push('"');
        for &b in used(data) {
            match b {
                b'"' | b'\\' => {
                    self.out.push('\\');
                    self.out.push(char::from(b));
                }
                0x20..=0x7E => self.out.push(char::from(b)),
                _ => {
                    self.out.push_str("\\u00");
                    push_hex(&mut self.out, b);
                }
            }
        }
        self.out.push('"');
    }
}

// ------------------------------------------------------------------ XML

/// A parsed element: its attributes, child elements and character data
/// (text and CDATA, entities decoded, line ends normalized).
pub(crate) struct XmlNode {
    pub(crate) name: String,
    attributes: Vec<(String, String)>,
    text: Vec<char>,
    children: Vec<XmlNode>,
}

fn is_name_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_' || c == ':' || u32::from(c) >= 0x80
}

fn is_name_char(c: char) -> bool {
    is_name_start(c) || c.is_ascii_digit() || c == '-' || c == '.'
}

/// Reads a subset of XML 1.0 that is enough for messages: elements,
/// attributes, character data, CDATA, comments, processing instructions,
/// the predefined entities and character references. A document type
/// declaration, and so any other entity, is rejected.
struct XmlParser {
    s: Vec<char>,
    i: usize,
}

impl XmlParser {
    fn peek(&self) -> Option<char> {
        self.s.get(self.i).copied()
    }

    fn starts(&self, word: &str) -> bool {
        has_prefix(&self.s, self.i, word)
    }

    fn space(&mut self) {
        while matches!(self.peek(), Some(c) if is_space(c)) {
            self.i += 1;
        }
    }

    fn find(&self, word: &str, from: usize) -> Option<usize> {
        (from..self.s.len()).find(|&at| has_prefix(&self.s, at, word))
    }

    fn skip_past(&mut self, end: &str) -> Result<()> {
        let at = self
            .find(end, self.i)
            .ok_or_else(|| invalid("unterminated"))?;
        self.i = at + end.len();
        Ok(())
    }

    fn misc(&mut self) -> Result<()> {
        loop {
            self.space();
            if self.starts("<!--") {
                self.i += 4;
                self.skip_past("-->")?;
            } else if self.starts("<?") {
                self.i += 2;
                self.skip_past("?>")?;
            } else if self.starts("<!") {
                return Err(invalid("a document type declaration"));
            } else {
                return Ok(());
            }
        }
    }

    fn name(&mut self) -> Result<String> {
        if !matches!(self.peek(), Some(c) if is_name_start(c)) {
            return Err(invalid("expected a name"));
        }
        let start = self.i;
        while matches!(self.peek(), Some(c) if is_name_char(c)) {
            self.i += 1;
        }
        Ok(self.s[start..self.i].iter().collect())
    }

    fn reference(&mut self, out: &mut Vec<char>) -> Result<()> {
        let semi = self
            .find(";", self.i)
            .ok_or_else(|| invalid("unterminated reference"))?;
        let r: Vec<char> = self.s[self.i..semi].to_vec();
        self.i = semi + 1;
        let text: String = r.iter().collect();
        match text.as_str() {
            "lt" => out.push('<'),
            "gt" => out.push('>'),
            "amp" => out.push('&'),
            "quot" => out.push('"'),
            "apos" => out.push('\''),
            _ if r.len() > 1 && r[0] == '#' => {
                let hexadecimal = r[1] == 'x';
                let digits = if hexadecimal { &r[2..] } else { &r[1..] };
                let radix = if hexadecimal { 16 } else { 10 };
                if digits.is_empty() || digits.len() > 8 {
                    return Err(invalid("bad character reference"));
                }
                let mut v: u32 = 0;
                for &c in digits {
                    if !c.is_ascii_digit() && !(hexadecimal && c.is_ascii_hexdigit()) {
                        return Err(invalid("bad character reference"));
                    }
                    v = v * radix + c.to_digit(radix).unwrap_or(0);
                }
                let allowed = v == 0x9
                    || v == 0xA
                    || v == 0xD
                    || (0x20..=0xD7FF).contains(&v)
                    || (0xE000..=0xFFFD).contains(&v)
                    || (0x10000..=0x10FFFF).contains(&v);
                match char::from_u32(v) {
                    Some(c) if allowed => out.push(c),
                    _ => return Err(invalid("character not allowed")),
                }
            }
            _ => return Err(invalid("unknown entity")),
        }
        Ok(())
    }

    /// Character data up to `stop` (not consumed), into `out`.
    fn chars(&mut self, out: &mut Vec<char>, stop: char, attribute: bool) -> Result<()> {
        while let Some(c) = self.peek() {
            if c == stop {
                break;
            }
            match c {
                '<' => return Err(invalid("< in an attribute")),
                '&' => {
                    self.i += 1;
                    self.reference(out)?;
                    continue;
                }
                '\r' => {
                    // CR LF and a lone CR are both a line end.
                    self.i += 1;
                    if self.peek() == Some('\n') {
                        self.i += 1;
                    }
                    out.push(if attribute { ' ' } else { '\n' });
                    continue;
                }
                '\n' | '\t' if attribute => out.push(' '),
                _ => out.push(c),
            }
            self.i += 1;
        }
        Ok(())
    }

    fn element(&mut self, depth: usize) -> Result<XmlNode> {
        let depth = depth + 1;
        if depth > MAX_DEPTH {
            return Err(invalid("nested too deeply"));
        }
        self.i += 1; // '<'
        let mut node = XmlNode {
            name: self.name()?,
            attributes: Vec::new(),
            text: Vec::new(),
            children: Vec::new(),
        };
        loop {
            let before = self.i;
            self.space();
            if self.i >= self.s.len() {
                return Err(invalid("unterminated start tag"));
            }
            if self.starts("/>") {
                self.i += 2;
                return Ok(node);
            }
            if self.peek() == Some('>') {
                self.i += 1;
                break;
            }
            if self.i == before {
                return Err(invalid("attributes must be separated by whitespace"));
            }
            let name = self.name()?;
            self.space();
            if self.peek() != Some('=') {
                return Err(invalid("expected ="));
            }
            self.i += 1;
            self.space();
            let quote = match self.peek() {
                Some(q) if q == '"' || q == '\'' => q,
                _ => return Err(invalid("expected a quote")),
            };
            self.i += 1;
            let mut value = Vec::new();
            self.chars(&mut value, quote, true)?;
            if self.i >= self.s.len() {
                return Err(invalid("unterminated attribute"));
            }
            self.i += 1;
            if node.attribute(&name).is_some() {
                return Err(invalid("repeated attribute"));
            }
            node.attributes.push((name, value.into_iter().collect()));
        }

        loop {
            if self.i >= self.s.len() {
                return Err(invalid("unterminated element"));
            }
            if self.starts("</") {
                self.i += 2;
                if self.name()? != node.name {
                    return Err(invalid("mismatched end tag"));
                }
                self.space();
                if self.peek() != Some('>') {
                    return Err(invalid("bad end tag"));
                }
                self.i += 1;
                return Ok(node);
            } else if self.starts("<!--") {
                self.i += 4;
                self.skip_past("-->")?;
            } else if self.starts("<![CDATA[") {
                self.i += 9;
                let end = self
                    .find("]]>", self.i)
                    .ok_or_else(|| invalid("unterminated CDATA"))?;
                let mut j = self.i;
                while j < end {
                    let mut c = self.s[j];
                    if c == '\r' {
                        if j + 1 < end && self.s[j + 1] == '\n' {
                            j += 1;
                        }
                        c = '\n';
                    }
                    node.text.push(c);
                    j += 1;
                }
                self.i = end + 3;
            } else if self.starts("<?") {
                self.i += 2;
                self.skip_past("?>")?;
            } else if self.starts("<!") {
                return Err(invalid("a declaration in content"));
            } else if self.peek() == Some('<') {
                let child = self.element(depth)?;
                node.children.push(child);
            } else {
                self.chars(&mut node.text, '<', false)?;
            }
        }
    }
}

/// Parses a whole XML document whose root element is `root`. Invalid if it
/// is not well-formed in the subset `XmlParser` takes.
pub(crate) fn parse_xml(input: &[u8], root: &str) -> Result<XmlNode> {
    let s = decode(input)?;
    let allowed = |c: &char| {
        let v = u32::from(*c);
        (v >= 0x20 || v == 0x9 || v == 0xA || v == 0xD) && v != 0xFFFE && v != 0xFFFF
    };
    if !s.iter().all(allowed) {
        return Err(invalid("character not allowed in XML"));
    }
    let mut p = XmlParser { s, i: 0 };
    if p.starts("<?xml") && matches!(p.s.get(5), Some(&c) if is_space(c)) {
        p.skip_past("?>")?;
    }
    p.misc()?;
    if p.peek() != Some('<') {
        return Err(invalid("no root element"));
    }
    let node = p.element(0)?;
    p.misc()?;
    if p.i != p.s.len() {
        return Err(invalid("text after the root element"));
    }
    if node.name != root {
        return Err(invalid(&format!("root element is not {root}")));
    }
    Ok(node)
}

impl XmlNode {
    fn attribute(&self, name: &str) -> Option<&str> {
        self.attributes
            .iter()
            .find(|a| a.0 == name)
            .map(|a| a.1.as_str())
    }

    /// The member elements of an element holding a message, which must have
    /// only whitespace between them.
    pub(crate) fn members(&self) -> Result<&[XmlNode]> {
        if !trim(&self.text).is_empty() {
            return Err(invalid("text in a message element"));
        }
        Ok(&self.children)
    }

    /// A number member's text: an element holding only its text,
    /// surrounding whitespace allowed.
    fn number_text(&self) -> Result<String> {
        if !self.children.is_empty() {
            return Err(invalid("an element in a number"));
        }
        Ok(trim(&self.text))
    }

    /// An integer member, as in JSON.
    pub(crate) fn int(&self, ctype: &str, bits: u32) -> Result<u64> {
        to_integer(&self.number_text()?, ctype, bits)
    }

    /// A float or double member, as in JSON.
    pub(crate) fn real(&self, ctype: &str) -> Result<f64> {
        to_real(&self.number_text()?, ctype)
    }

    /// A string member, into `dst`: the element's text, each character one
    /// byte, or with encoding="hex" the bytes in hexadecimal.
    pub(crate) fn bytes(&self, dst: &mut [u8]) -> Result<()> {
        if !self.children.is_empty() {
            return Err(invalid("an element in a string"));
        }
        match self.attribute("encoding") {
            None => return text_to_bytes(&self.text, dst),
            Some("hex") => {}
            Some(_) => return Err(invalid("unknown encoding")),
        }
        let digits: Vec<char> = trim(&self.text).chars().collect();
        if digits.len() % 2 == 1
            || digits.len() / 2 > dst.len()
            || !digits.iter().all(char::is_ascii_hexdigit)
        {
            return Err(invalid("bad hex"));
        }
        dst.fill(0);
        for (d, pair) in dst.iter_mut().zip(digits.chunks(2)) {
            let high = pair[0].to_digit(16).unwrap_or(0);
            let low = pair[1].to_digit(16).unwrap_or(0);
            *d = (high * 16 + low) as u8;
        }
        Ok(())
    }
}

/// Writes the canonical XML form: no declaration, no whitespace between
/// elements, one element per member.
#[derive(Default)]
pub(crate) struct XmlWriter {
    out: String,
}

impl XmlWriter {
    pub(crate) fn finish(self) -> String {
        self.out
    }

    pub(crate) fn open(&mut self, name: &str) {
        self.out.push('<');
        self.out.push_str(name);
        self.out.push('>');
    }

    pub(crate) fn close(&mut self, name: &str) {
        self.out.push_str("</");
        self.out.push_str(name);
        self.out.push('>');
    }

    fn element(&mut self, name: &str, text: &str) {
        self.open(name);
        self.out.push_str(text);
        self.close(name);
    }

    pub(crate) fn i32(&mut self, name: &str, v: i32) {
        self.element(name, &v.to_string());
    }

    pub(crate) fn u32(&mut self, name: &str, v: u32) {
        self.element(name, &v.to_string());
    }

    pub(crate) fn i64(&mut self, name: &str, v: i64) {
        self.element(name, &v.to_string());
    }

    pub(crate) fn u64(&mut self, name: &str, v: u64) {
        self.element(name, &v.to_string());
    }

    pub(crate) fn f32(&mut self, name: &str, v: f32) {
        self.element(name, &real_text(f64::from(v), true));
    }

    pub(crate) fn f64(&mut self, name: &str, v: f64) {
        self.element(name, &real_text(v, false));
    }

    /// A string member: its bytes up to the trailing NULs, escaped, or, if
    /// any byte is not printable ASCII, in hexadecimal with encoding="hex".
    pub(crate) fn bytes(&mut self, name: &str, data: &[u8]) {
        let used = used(data);
        if used.iter().any(|&b| !(0x20..=0x7E).contains(&b)) {
            self.out.push('<');
            self.out.push_str(name);
            self.out.push_str(" encoding=\"hex\">");
            for &b in used {
                push_hex(&mut self.out, b);
            }
            self.close(name);
            return;
        }
        self.open(name);
        for &b in used {
            match b {
                b'<' => self.out.push_str("&lt;"),
                b'>' => self.out.push_str("&gt;"),
                b'&' => self.out.push_str("&amp;"),
                b'"' => self.out.push_str("&quot;"),
                b'\'' => self.out.push_str("&apos;"),
                _ => self.out.push(char::from(b)),
            }
        }
        self.close(name);
    }
}

// ------------------------------------------------------------------ BSON

const BSON_DOUBLE: u8 = 0x01;
const BSON_STRING: u8 = 0x02;
const BSON_DOCUMENT: u8 = 0x03;
const BSON_ARRAY: u8 = 0x04;
const BSON_BINARY: u8 = 0x05;
const BSON_UNDEFINED: u8 = 0x06;
const BSON_OBJECT_ID: u8 = 0x07;
const BSON_BOOL: u8 = 0x08;
const BSON_DATETIME: u8 = 0x09;
const BSON_NULL: u8 = 0x0A;
const BSON_REGEX: u8 = 0x0B;
const BSON_DB_POINTER: u8 = 0x0C;
const BSON_JAVASCRIPT: u8 = 0x0D;
const BSON_SYMBOL: u8 = 0x0E;
const BSON_CODE_WITH_SCOPE: u8 = 0x0F;
const BSON_INT32: u8 = 0x10;
const BSON_TIMESTAMP: u8 = 0x11;
const BSON_INT64: u8 = 0x12;
const BSON_DECIMAL128: u8 = 0x13;
const BSON_MIN_KEY: u8 = 0xFF;
const BSON_MAX_KEY: u8 = 0x7F;

/// The high word of a Decimal128 holding an integer: exponent 0 (6176
/// biased), positive.
const DECIMAL128_INTEGER_HIGH: u64 = 6176 << 49;
/// The quiet NaN every NaN is written as.
const CANONICAL_NAN: u64 = 0x7FF8_0000_0000_0000;

/// One element. Which fields hold its value depends on its type: `data` for
/// a string (without its NUL) or binary (with `subtype`); `integer` for
/// int32 and int64; `number` for double; `low` and `high` for Decimal128;
/// `document` for an embedded document or array.
#[derive(Default)]
pub(crate) struct BsonElement {
    pub(crate) name: String,
    kind: u8,
    data: Vec<u8>,
    subtype: u8,
    integer: i64,
    number: f64,
    low: u64,
    high: u64,
    document: Vec<BsonElement>,
}

/// Reads a document or an element's value between a position and an end,
/// checking every length against the bytes there are.
struct BsonParser<'a> {
    s: &'a [u8],
}

impl BsonParser<'_> {
    fn int32(&self, at: usize) -> i64 {
        let mut b = [0; 4];
        b.copy_from_slice(&self.s[at..at + 4]);
        i64::from(i32::from_le_bytes(b))
    }

    fn uint64(&self, at: usize) -> u64 {
        let mut b = [0; 8];
        b.copy_from_slice(&self.s[at..at + 8]);
        u64::from_le_bytes(b)
    }

    fn document(&self, pos: usize, end: usize, depth: usize) -> Result<(Vec<BsonElement>, usize)> {
        if depth > MAX_DEPTH || end - pos < 5 {
            return Err(invalid("bad document"));
        }
        let length = self.int32(pos);
        if length < 5 || length > (end - pos) as i64 {
            return Err(invalid("bad document length"));
        }
        let last = pos + length as usize - 1;
        if self.s[last] != 0 {
            return Err(invalid("no document terminator"));
        }
        let mut elements = Vec::new();
        let mut at = pos + 4;
        while at < last {
            let (e, next) = self.element(at, last, depth)?;
            elements.push(e);
            at = next;
        }
        Ok((elements, last + 1))
    }

    fn cstring(&self, at: usize, end: usize) -> Result<(String, usize)> {
        let nul = self.s[at..end]
            .iter()
            .position(|&b| b == 0)
            .ok_or_else(|| invalid("unterminated cstring"))?;
        match std::str::from_utf8(&self.s[at..at + nul]) {
            Ok(text) => Ok((text.to_string(), at + nul + 1)),
            Err(_) => Err(invalid("not UTF-8")),
        }
    }

    fn string(&self, at: usize, end: usize) -> Result<(Vec<u8>, usize)> {
        if end - at < 4 {
            return Err(invalid("bad string"));
        }
        let length = self.int32(at);
        if length < 1 || length > (end - at - 4) as i64 {
            return Err(invalid("bad string length"));
        }
        let nul = at + 4 + length as usize - 1;
        if self.s[nul] != 0 {
            return Err(invalid("unterminated string"));
        }
        let text = &self.s[at + 4..nul];
        if std::str::from_utf8(text).is_err() {
            return Err(invalid("not UTF-8"));
        }
        Ok((text.to_vec(), nul + 1))
    }

    fn fixed(at: usize, end: usize, width: usize) -> Result<usize> {
        if end - at < width {
            return Err(invalid("cut short"));
        }
        Ok(at + width)
    }

    fn element(&self, at: usize, end: usize, depth: usize) -> Result<(BsonElement, usize)> {
        let mut e = BsonElement {
            kind: self.s[at],
            ..BsonElement::default()
        };
        let (name, start) = self.cstring(at + 1, end)?;
        e.name = name;
        let next = match e.kind {
            BSON_DOUBLE => {
                let next = Self::fixed(start, end, 8)?;
                e.number = f64::from_bits(self.uint64(start));
                next
            }
            BSON_STRING | BSON_JAVASCRIPT | BSON_SYMBOL => {
                let (data, next) = self.string(start, end)?;
                e.data = data;
                next
            }
            BSON_DOCUMENT | BSON_ARRAY => {
                let (document, next) = self.document(start, end, depth + 1)?;
                e.document = document;
                next
            }
            BSON_BINARY => {
                if end - start < 5 {
                    return Err(invalid("bad binary"));
                }
                let length = self.int32(start);
                if length < 0 || length > (end - start - 5) as i64 {
                    return Err(invalid("bad binary length"));
                }
                let length = length as usize;
                e.subtype = self.s[start + 4];
                e.data = self.s[start + 5..start + 5 + length].to_vec();
                start + 5 + length
            }
            BSON_UNDEFINED | BSON_NULL | BSON_MIN_KEY | BSON_MAX_KEY => start,
            BSON_OBJECT_ID => Self::fixed(start, end, 12)?,
            BSON_BOOL => {
                let next = Self::fixed(start, end, 1)?;
                if self.s[start] > 1 {
                    return Err(invalid("bad bool"));
                }
                next
            }
            BSON_DATETIME | BSON_TIMESTAMP => Self::fixed(start, end, 8)?,
            BSON_INT32 => {
                let next = Self::fixed(start, end, 4)?;
                e.integer = self.int32(start);
                next
            }
            BSON_INT64 => {
                let next = Self::fixed(start, end, 8)?;
                e.integer = self.uint64(start) as i64;
                next
            }
            BSON_DECIMAL128 => {
                let next = Self::fixed(start, end, 16)?;
                e.low = self.uint64(start);
                e.high = self.uint64(start + 8);
                next
            }
            BSON_REGEX => {
                let (_, next) = self.cstring(start, end)?;
                self.cstring(next, end)?.1
            }
            BSON_DB_POINTER => {
                let (_, next) = self.string(start, end)?;
                Self::fixed(next, end, 12)?
            }
            BSON_CODE_WITH_SCOPE => {
                // int32 total length, then a string and a document filling it.
                if end - start < 4 {
                    return Err(invalid("bad code with scope"));
                }
                let length = self.int32(start);
                if length < 4 || length > (end - start) as i64 {
                    return Err(invalid("bad code with scope length"));
                }
                let stop = start + length as usize;
                let (_, next) = self.string(start + 4, stop)?;
                let (_, next) = self.document(next, stop, depth + 1)?;
                if next != stop {
                    return Err(invalid("bad code with scope length"));
                }
                next
            }
            // An unknown type: its length is unknown, so nothing after it
            // can be read.
            _ => return Err(invalid("unknown element type")),
        };
        Ok((e, next))
    }
}

/// Parses a whole BSON document: its length must be exactly the input's.
/// Its elements, in order, repeats and all.
pub(crate) fn parse_bson(input: &[u8]) -> Result<Vec<BsonElement>> {
    let p = BsonParser { s: input };
    let (elements, end) = p.document(0, input.len(), 1)?;
    if end != input.len() {
        return Err(invalid("bytes after the document"));
    }
    Ok(elements)
}

/// A Decimal128 (BID) as a whole number of at most 64 bits, as its sign and
/// magnitude; `None` if it is infinite, NaN, not canonical, not whole, or
/// larger.
fn decimal_integer(low: u64, high: u64) -> Option<(bool, u64)> {
    let negative = high >> 63 != 0;
    if (high >> 61) & 3 == 3 {
        return None;
    }
    let exponent = ((high >> 49) & 0x3FFF) as i32 - 6176;
    let mut coefficient = (u128::from(high & 0x1_FFFF_FFFF_FFFF) << 64) | u128::from(low);
    if coefficient >= 10u128.pow(34) {
        return None;
    }
    if coefficient == 0 {
        return Some((false, 0));
    }
    if exponent < 0 {
        // The coefficient is not zero, so this ends within 34 places.
        for _ in 0..-exponent {
            if coefficient % 10 != 0 {
                return None;
            }
            coefficient /= 10;
        }
    } else if exponent > 0 {
        if exponent > 20 {
            return None;
        }
        coefficient = coefficient.checked_mul(10u128.pow(exponent as u32))?;
    }
    if coefficient > u128::from(u64::MAX) {
        return None;
    }
    Some((negative, coefficient as u64))
}

impl BsonElement {
    /// An integer member, from an int32, int64, Decimal128 or double that is
    /// a whole number in its range.
    pub(crate) fn int(&self, ctype: &str, bits: u32) -> Result<u64> {
        let value = match self.kind {
            BSON_INT32 | BSON_INT64 => Some((self.integer < 0, self.integer.unsigned_abs())),
            BSON_DECIMAL128 => decimal_integer(self.low, self.high),
            BSON_DOUBLE => {
                let d = self.number;
                if !d.is_finite() || d != d.trunc() || d.abs() >= 18_446_744_073_709_551_616.0 {
                    return Err(invalid("not a whole number"));
                }
                Some((d < 0.0, d.abs() as u64))
            }
            _ => return Err(invalid("not a number")),
        };
        let (negative, magnitude) =
            value.ok_or_else(|| invalid("not a whole number of at most 64 bits"))?;
        fit_integer(negative, magnitude, ctype, bits)
    }

    /// A float or double member, from a double (rounded to the type, too
    /// large for it invalid), int32 or int64.
    pub(crate) fn real(&self, ctype: &str) -> Result<f64> {
        let is_float = ctype == "float";
        match self.kind {
            BSON_INT32 | BSON_INT64 if is_float => return Ok(f64::from(self.integer as f32)),
            BSON_INT32 | BSON_INT64 => return Ok(self.integer as f64),
            BSON_DOUBLE => {}
            _ => return Err(invalid("not a number")),
        }
        let d = self.number;
        if !is_float || d.is_nan() {
            return Ok(d);
        }
        // Halfway from the largest float to 2^128 and beyond round to
        // infinity: too large.
        if !d.is_infinite() && d.abs() >= f64::from_bits(0x47EF_FFFF_F000_0000) {
            return Err(invalid("too large for a float"));
        }
        Ok(f64::from(d as f32))
    }

    /// A string member, into `dst`, from a string or binary (subtype 0) of
    /// at most `dst.len()` bytes, zero-filled.
    pub(crate) fn bytes(&self, dst: &mut [u8]) -> Result<()> {
        if self.kind != BSON_STRING && (self.kind != BSON_BINARY || self.subtype != 0) {
            return Err(invalid("not a string"));
        }
        if self.data.len() > dst.len() {
            return Err(invalid("string too long"));
        }
        dst.fill(0);
        dst[..self.data.len()].copy_from_slice(&self.data);
        Ok(())
    }

    /// A nested message member's elements.
    pub(crate) fn document(&self) -> Result<&[BsonElement]> {
        if self.kind != BSON_DOCUMENT {
            return Err(invalid("not a document"));
        }
        Ok(&self.document)
    }
}

/// Builds a BSON document: each, the outermost included, is
/// `begin_document()` ... `end_document()`; an embedded one is named first
/// with `document(name)`.
#[derive(Default)]
pub(crate) struct BsonWriter {
    out: Vec<u8>,
    starts: Vec<usize>,
}

impl BsonWriter {
    pub(crate) fn finish(self) -> Vec<u8> {
        self.out
    }

    pub(crate) fn begin_document(&mut self) {
        self.starts.push(self.out.len());
        self.out.extend_from_slice(&[0; 4]);
    }

    pub(crate) fn end_document(&mut self) {
        self.out.push(0);
        let start = self.starts.pop().unwrap_or(0);
        let length = (self.out.len() - start) as u32;
        self.out[start..start + 4].copy_from_slice(&length.to_le_bytes());
    }

    fn head(&mut self, kind: u8, name: &str) {
        self.out.push(kind);
        self.out.extend_from_slice(name.as_bytes());
        self.out.push(0);
    }

    pub(crate) fn document(&mut self, name: &str) {
        self.head(BSON_DOCUMENT, name);
    }

    /// Types up to 32 bits but uint32_t are int32 (a char as signed).
    pub(crate) fn i32(&mut self, name: &str, v: i32) {
        self.head(BSON_INT32, name);
        self.out.extend_from_slice(&v.to_le_bytes());
    }

    pub(crate) fn u32(&mut self, name: &str, v: u32) {
        self.i64(name, i64::from(v));
    }

    pub(crate) fn i64(&mut self, name: &str, v: i64) {
        self.head(BSON_INT64, name);
        self.out.extend_from_slice(&v.to_le_bytes());
    }

    /// A uint64_t above 2^63-1 is a Decimal128, so no tool sees it negative.
    pub(crate) fn u64(&mut self, name: &str, v: u64) {
        if v <= i64::MAX as u64 {
            self.i64(name, v as i64);
            return;
        }
        self.head(BSON_DECIMAL128, name);
        self.out.extend_from_slice(&v.to_le_bytes());
        self.out
            .extend_from_slice(&DECIMAL128_INTEGER_HIGH.to_le_bytes());
    }

    pub(crate) fn f32(&mut self, name: &str, v: f32) {
        self.f64(name, f64::from(v));
    }

    pub(crate) fn f64(&mut self, name: &str, v: f64) {
        self.head(BSON_DOUBLE, name);
        let bits = if v.is_nan() {
            CANONICAL_NAN
        } else {
            v.to_bits()
        };
        self.out.extend_from_slice(&bits.to_le_bytes());
    }

    /// A string member: its bytes up to the trailing NULs, as a string if
    /// they are UTF-8 holding no NUL, otherwise as binary (subtype 0).
    pub(crate) fn bytes(&mut self, name: &str, data: &[u8]) {
        let used = used(data);
        if !used.contains(&0) && std::str::from_utf8(used).is_ok() {
            self.head(BSON_STRING, name);
            self.out
                .extend_from_slice(&(used.len() as u32 + 1).to_le_bytes());
            self.out.extend_from_slice(used);
            self.out.push(0);
            return;
        }
        self.head(BSON_BINARY, name);
        self.out
            .extend_from_slice(&(used.len() as u32).to_le_bytes());
        self.out.push(0);
        self.out.extend_from_slice(used);
    }
}
